mapper.select:
select *
from pay_details d
where d.id = #{id}

select *
from pay_details d
where d.remark = #{remark}

select *
from pay_details d
where d.order_id = #{orderId}

mapper.update:
update pay_details
set `state`=#{state},
    pay_time=#{time},
    trade_no=#{tradeNo}
where id = #{id}

mapper.select:
select s.id,s.classify,s.order_id as orderId,s.money,s.user_id as userId, s.state,s.create_time as createTime,s.pay_time as payTime,u.user_name as userName,u.phone from pay_details s left join tb_user u on u.user_id=s.user_id where 1=1
and str_to_date(s.create_time, '%Y-%m-%d') between str_to_date(#{startTime}, '%Y-%m-%d') AND str_to_date(#{endTime}, '%Y-%m-%d')
and u.user_id=#{userId}
and s.state=#{state}
and s.state!=-1
group by s.id order by s.create_time desc

select sum(money) from pay_details where str_to_date(create_time, '%Y-%m-%d') BETWEEN str_to_date(#{createTime}, '%Y-%m-%d') AND str_to_date(#{endTime}, '%Y-%m-%d')
and user_id=#{userId}
and state=1
